SourceCode.Declaration:
/// <summary>
/// Request contract for one notebook cell. Cells with the same SessionId share variables,
/// script classes and imports in the AOS process. Commit = false rolls the cell's database
/// work back; Commit = true commits it.
/// </summary>
[DataContract]
public final class MXTXppNotebookCellRequest
{
    str sessionId;
    str sourceCode;
    boolean commit;
    str requestId;
}

Method.Source:
[DataMember("SessionId")]
public str parmSessionId(str _sessionId = sessionId)
{
    sessionId = _sessionId;
    return sessionId;
}

[DataMember("SourceCode")]
public str parmSourceCode(str _sourceCode = sourceCode)
{
    sourceCode = _sourceCode;
    return sourceCode;
}

[DataMember("Commit")]
public boolean parmCommit(boolean _commit = commit)
{
    commit = _commit;
    return commit;
}

[DataMember("RequestId")]
public str parmRequestId(str _requestId = requestId)
{
    requestId = _requestId;
    return requestId;
}
